def is_convex_polygon(points):
    if len(points) < 3:
        return False
    n = len(points)
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        if cross == 0:
            return False
    sign = None
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        if cross < 0:
            if sign is None:
                sign = -1
            elif sign > 0:
                return False
        elif cross > 0:
            if sign is None:
                sign = 1
            elif sign < 0:
                return False
    return True
```

