def is_convex_polygon(points):
    if len(points) < 3:
        return False

    def cross(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    prev_cross = None
    for i in range(len(points)):
        a, b, c = points[i], points[(i + 1) % len(points)], points[(i + 2) % len(points)]
        current_cross = cross(a, b, c)
        if prev_cross is None:
            prev_cross = current_cross
        elif current_cross * prev_cross < 0:
            return False
        prev_cross = current_cross

    return True
```

