        return len(grid1) == len(grid2) and all(len(row) == len(grid2) for row in grid1)

    # Direct match
    if grid1 == grid2:
        return True

    # Try 90-degree rotation
    if len(grid1) == len(grid1[0]):
        n = len(grid1)
        rotated = [[grid1[n - j - 1][i] for j in range(n)] for i in range(n)]
        if rotated == grid2:
            return True

    # Try 180-degree rotation
    rotated = [row[::-1] for row in grid1][::-1]
    if rotated == grid2:
        return True

    # Try 270-degree rotation
    if len(grid1) == len(grid1[0]):
        n = len(grid1)
        rotated = [[grid1[j][n - i - 1] for j in range(n)] for i in range(n)]
        if rotated == grid2:
            return True

    return False
