def is_checkerboard(grid):
    """Determines whether a 2D grid forms a valid checkerboard pattern, i.e. a grid where every
    cell differs from its horizontal and vertical neighbors and the two distinct values alternate
    based on whether the sum of a cell's row and column index is even or odd.
    """

    if not grid or not grid[0]:
        return True

    # The first two elements must be different
    if grid[0][0] == grid[0][1]:
        return False

    rows, cols = len(grid), len(grid[0])
    for i in range(rows):
        for j in range(cols):
            # Skip the last element in each row since it has no right neighbor
            if j == cols - 1:
                continue

            # Check for a right neighbor
            if grid[i][j] == grid[i][j + 1]:
                return False

            # Skip the last row since it has no bottom neighbor
            if i == rows - 1:
