def parse_url_parts(url):
    result = {'scheme': '', 'host': '', 'path': '', 'query': ''}

    if not url:
        return result

    scheme_end = url.find('://')
    if scheme_end != -1:
        result['scheme'] = url[:scheme_end]
        url = url[scheme_end+3:]
    else:
        return result

    host_end = url.find('/')
    if host_end == -1:
        host_end = url.find('?')
    if host_end == -1:
        result['host'] = url
    else:
        result['host'] = url[:host_end]
        url = url[host_end:]

    if url.startswith('/'):
        path_end = url.find('?')
        if path_end == -1:
            path_end = len(url)
        result['path'] = url[:path_end]
        if path_end < len(url):
            result['query'] = url[path_end+1:]

    return result
```

