def rate_limiter_allowed(timestamps, limit, window):
    if not timestamps:
        return []
    allowed = [False] * len(timestamps)
    timestamps_with_idx = [(t, i) for i, t in enumerate(timestamps)]
    sorted_by_t = sorted(timestamps_with_idx, key=lambda x: x[0])
    pos = 0
    for i, t in enumerate(timestamps):
        while pos < len(sorted_by_t) and sorted_by_t[pos][0] <= t - window:
            pos += 1
        if len(sorted_by_t) - pos <= limit:
            allowed[i] = True
    return allowed
```

