                    found = True
                    break
            if not found:
                cart.append((item, qty, price))
        elif event[0] == 'remove':
            item, qty = event[1], event[2]
            for i in range(len(cart)):
                if cart[i][0] == item:
                    if cart[i][1] <= qty:
