def shopping_cart_total(events):
    """
    Simulates a shopping cart with add, remove, and clear operations.

    Args:
        events: A list of events, each of the form ("add", item, qty, price),
            ("remove", item, qty), or ("clear",).
    Returns:
        The total cost of the cart, computed as the sum over items of quantity times unit price.
    """
    cart = {}  # Tracks quantity and unit price per item

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                cart[item] = (cart[item][0] + qty, price)  # Update quantity, keep price
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart and cart[item][0] > qty:
                cart[item] = (cart[item][0] - qty, cart[item][1])
            elif item in cart:
                del cart[item]
        elif event[0] == "clear":
            cart.clear()

    return sum(qty * price for qty, price in cart.values())
