    if direction == 1:  # Going up
        if start_floor in requests:
            stop_order = [start_floor]
        else:
            stop_order = []
        current = start_floor
        while current < top_floor:
            current += 1
            if current in requests:
                stop_order.append(current)
        if stop_order and stop_order[-1] != top_floor:
            stop_order.append(top_floor)
